// ---------------- 9d: boss, legendary and team weeks ----------------

const legendWeek = (id: string, name: string, offset: number, species: string[], desc: string, extraMods: Json[], extraRule: string, goals: Json[], title: string, color: string, icon: string): Spec => ({
  id, name, when: week(offset), desc,
  rule: `Legendary gates for ${species.map(cap).join(', ')} turn up on far more stages (about 1 in 2), skip their usual conditions and one extra is allowed per region.${extraRule ? ' ' + extraRule : ''}`,
  mods: [{ kind: 'legendaryFocus', species, weight: 12, gateChance: 0.5 }, ...extraMods],
  goals, reward: { researchPoints: 500, title }, color, icon, tags: ['legendary'],
});
const teamWeek = (id: string, name: string, offset: number, teams: string[], desc: string, pool: string, title: string, color: string, mods: Json[], modText: string): Spec => ({
  id, name, when: week(offset), desc,
  rule: `The evil team of your run is ${teams.length > 1 ? 'one of ' + teams.map(cap).join(' and ') : cap(teams[0]!)} (by seed). ${modText}`.trim(),
  mods: [{ kind: 'evilTeamFocus', teams }, ...mods],
  goals: [G.trainers(15), G.events(6), G.gyms(2)], reward: { researchPoints: 400, title, pool }, color, icon: 'item.scanner', tags: ['team'],
});

