// ---------------- 9f: rule-bending and challenge weeks (the ones with a real rule today) ----------------

const stats = (value: number, keys = ['atk', 'def', 'spa', 'spd', 'spe']): Json[] => keys.map((stat) => ({ kind: 'statMultiplier', stat, value }));
const genWeek = (id: string, name: string, offset: number, gen: number, region: string, color: string): Spec => ({
  id, name, when: week(offset), desc: `A throwback to ${region}: its Pokémon crowd the routes.`,
  rule: `Generation ${gen} Pokémon appear eight times as often.`,
  mods: [{ kind: 'speciesEncounterWeight', generation: gen, value: 8 }],
  goals: [G.catches(12), G.wins(25), G.gyms(2)], reward: { researchPoints: 300, title: `${region} Throwback` }, color, icon: 'item.map', tags: ['throwback'],
});

